alter table public.site_activities add column if not exists detail_key text;
comment on column public.site_activities.detail_key is 'Stable key into activity-details.js; retained when duplicating a session.';
with templates(detail_key) as (values ('mind-body-balance-20261122'),('beitou-20261010'),('xizhi-gongbeidian-20261011'),('muzha-20261017'),('keelung-xiandong-20261018'),('xinzhuang-2026-10-24'),('yuanshan-20261025'),('sheliao-2026-10-31'),('zhishanyan-20261101'),('monga'),('dalongdong-20261108'),('xinzhuang-faith-20261114'),('taipei-shikoku-20261115'),('guandu-2026-11-21'),('neihu-20261122'),('dadaocheng-20261128'),('xizhi-20261129'),('tamsui-20261205'),('songshan-20261206'),('ximen-20261213'),('muzha-zhubai-20261212'),('temple-songshan-20261026')), matches as (select a.id,min(t.detail_key) as detail_key from public.site_activities a join templates t on regexp_replace(a.slug, '(?:-[0-9]{8}|-[0-9]{4}-[0-9]{2}-[0-9]{2})+$', '')=regexp_replace(t.detail_key, '(?:-[0-9]{8}|-[0-9]{4}-[0-9]{2}-[0-9]{2})+$', '') where a.detail_key is null group by a.id having count(*)=1) update public.site_activities a set detail_key=m.detail_key from matches m where a.id=m.id;